  const validateSafeHttpUrl = (rawUrl: string): URL | null => {
    try {
      const parsed = new URL(rawUrl.trim());
      if (parsed.protocol !== "http:" && parsed.protocol !== "https:") return null;
      const host = parsed.hostname.toLowerCase();
      if (
        host === "localhost" ||
        host === "127.0.0.1" ||
        host === "0.0.0.0" ||
        host === "::1" ||
        host.endsWith(".local") ||
        /^10\./.test(host) ||
        /^192\.168\./.test(host) ||
        /^169\.254\./.test(host) ||
        /^172\.(1[6-9]|2\d|3[01])\./.test(host)
      ) {
        return null;
      }
      return parsed;
    } catch {
      return null;
    }
  };

  const parseMcpJsonOrSse = (rawText: string): any => {
    const trimmed = rawText.trim();
    if (!trimmed) return null;
    try {
      return JSON.parse(trimmed);
    } catch {
      // Parse SSE `data: {...}` lines
      const lines = trimmed.split(/\r?\n/);
      let lastParsed: any = null;
      for (const line of lines) {
        if (line.startsWith("data:")) {
          const payload = line.slice(5).trim();
          if (payload && payload !== "[DONE]") {
            try {
              lastParsed = JSON.parse(payload);
            } catch {}
          }
        }
      }
      return lastParsed;
    }
  };

  const sendMcpJsonRpc = async (
    endpoint: string,
    method: string,
    params: Record<string, any> | undefined,
    extraHeaders?: Record<string, string>,
    sessionId?: string
  ) => {
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      Accept: "application/json, text/event-stream",
      ...(extraHeaders || {}),
    };
    if (sessionId) {
      headers["mcp-session-id"] = sessionId;
    }
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 12000);
    try {
      const resp = await fetch(endpoint, {
        method: "POST",
        headers,
        body: JSON.stringify({
          jsonrpc: "2.0",
          id: Date.now(),
          method,
          params: params || {},
        }),
        signal: controller.signal,
      });
      const text = await resp.text();
      const respSessionId = resp.headers.get("mcp-session-id") || sessionId;
      const parsed = parseMcpJsonOrSse(text);
      if (!resp.ok) {
        throw new Error(parsed?.error?.message || `HTTP ${resp.status}: ${text.slice(0, 160)}`);
      }
      if (parsed?.error) {
        throw new Error(parsed.error.message || JSON.stringify(parsed.error));
      }
      return {
        data: parsed?.result ?? parsed,
        sessionId: respSessionId,
      };
    } finally {
      clearTimeout(timer);
    }
  };

